// trust.rs — embedded public-key trust anchor + ed25519 verify + sha256.
//
// Ported from Vala trust_store.vala. The embedded key (EMBEDDED_PUBKEY,
// 32 raw bytes) is generated by build.rs from the PEM and is the ONLY trust
// anchor. No key is ever read from disk. Verification is always on; there
// is no skip-verify path.

use ed25519_dalek::{Signature, VerifyingKey, SIGNATURE_LENGTH};
use sha2::{Digest, Sha256};

include!(concat!(env!("OUT_DIR"), "/embedded_pubkey.rs"));

/// Verify an ed25519 detached signature against the embedded public key.
pub fn verify_signature(data: &[u8], signature: &[u8]) -> bool {
    if signature.len() != SIGNATURE_LENGTH || EMBEDDED_PUBKEY.len() != 32 {
        return false;
    }
    let Ok(vk) = VerifyingKey::from_bytes(&EMBEDDED_PUBKEY) else {
        return false;
    };
    let Ok(sig) = Signature::from_slice(signature) else {
        return false;
    };
    vk.verify_strict(data, &sig).is_ok()
}

/// Compute the sha256 hex digest of a file's contents.
pub fn sha256_file(path: &str) -> Option<String> {
    let data = std::fs::read(path).ok()?;
    let mut hasher = Sha256::new();
    hasher.update(&data);
    Some(hex::encode(hasher.finalize()))
}

/// Verify a file's sha256 matches the expected hex string.
pub fn verify_agent(path: &str, expected_sha256: &str) -> bool {
    match sha256_file(path) {
        Some(actual) => actual.eq_ignore_ascii_case(expected_sha256),
        None => false,
    }
}

/// Verify the sha256 of each native payload file against the release manifest.
/// (trust-verification: "Native payload verification via the release manifest").
pub fn verify_payload(path: &str, expected_sha256: &str) -> bool {
    verify_agent(path, expected_sha256)
}
